875	type Summary = { id: string; slug: string; title: string };
876	
877	function answeredCount(draft: IntakeDraft) {
878	  return draft.messages.filter((m) => m.role === "user").length;
879	}
880	
881	function draftLabel(draft: IntakeDraft) {
882	  if (draft.profile) return "Answers ready to check";
883	  const n = answeredCount(draft);
884	  return `${n} ${n === 1 ? "answer" : "answers"} so far`;
885	}
886	
887	/** Registries this person already has, plus any answers they haven't finished. */
888	export function ResumeList() {
889	  const [registries, setRegistries] = useState<Summary[]>([]);
890	  const [drafts, setDrafts] = useState<IntakeDraft[]>([]);
891	  const [confirming, setConfirming] = useState<string | null>(null);
892	  const [busy, setBusy] = useState(false);
893	  const [error, setError] = useState("");
894	
895	  const load = useCallback(async () => {
896	    if (authEnabled) {
897	      const { data } = await getBrowserSupabase()!.auth.getSession();
898	      if (!data.session) return;
899	    }
900	    const [r, d] = await Promise.all([
901	      api<{ registries: Summary[] }>("/api/registries").catch(() => null),
902	      api<{ drafts: IntakeDraft[] }>("/api/drafts").catch(() => null),
903	    ]);
904	    if (r) setRegistries(r.registries);
905	    if (d) setDrafts(d.drafts);
906	  }, []);
907	
908	  useEffect(() => {
909	    void load();
910	  }, [load]);
911	
912	  async function remove(task: () => Promise<unknown>) {
913	    setBusy(true);
914	    setError("");
915	    try {
916	      await task();
917	      setConfirming(null);
918	      await load();
919	    } catch (e) {
920	      setError(e instanceof Error ? e.message : "That didn't work. Try again.");
921	    } finally {
922	      setBusy(false);
923	    }
924	  }
925	
926	  const unfinished = drafts.find((d) => !d.registryId && (answeredCount(d) > 0 || d.profile));
927	  const startingOver = new Map(drafts.filter((d) => d.registryId && answeredCount(d) > 0).map((d) => [d.registryId, d]));
928	
929	  if (!registries.length && !unfinished) return null;
930	
931	  const confirmRow = (key: string, prompt: string, onConfirm: () => void) =>
932	    confirming === key && (
933	      <div className="flex flex-wrap items-center justify-between gap-3 pb-3 text-[14px]" role="alertdialog" aria-label={prompt}>
934	        <span className="text-muted">{prompt}</span>
935	        <span className="flex gap-2">
936	          <button className="btn-quiet px-3 py-1.5 text-[13px]" onClick={() => setConfirming(null)} disabled={busy}>
937	            Keep it
938	          </button>
939	          <button className="btn-primary px-3 py-1.5 text-[13px]" onClick={onConfirm} disabled={busy}>
940	            {busy ? "Deleting…" : "Delete"}
941	          </button>
942	        </span>
943	      </div>
944	    );
945	
946	  return (
947	    <section aria-labelledby="yours" className="space-y-3 rounded-xl bg-surface px-5 py-4">
948	      <h2 id="yours" className="text-[13px] text-muted">
949	        Your registries
950	      </h2>
951	
952	      <ul className="divide-y divide-line border-y border-line">
953	        {unfinished && (
954	          <li>
955	            <div className="flex items-center justify-between gap-4 py-3">
956	              <div className="min-w-0">
957	                <p className="truncate font-serif text-[19px] font-semibold">A new registry</p>
958	                <p className="text-[13px] text-muted">{draftLabel(unfinished)}</p>
959	              </div>
960	              <div className="flex shrink-0 items-center gap-3">
961	                <button className="link text-[13px]" onClick={() => setConfirming(unfinished.id)}>
962	                  Discard
963	                </button>
964	                <Link href={`/start?draft=${unfinished.id}`} className="btn-primary px-4 py-2.5">
965	                  Finish answers
966	                </Link>
967	              </div>
968	            </div>
969	            {confirmRow(unfinished.id, "Discard these answers?", () =>
970	              void remove(() => api(`/api/drafts/${unfinished.id}`, { method: "DELETE" })),
971	            )}
972	          </li>
973	        )}
974	        {registries.map((r) => {
975	          const over = startingOver.get(r.id);
976	          return (
977	            <li key={r.id}>
978	              <div className="flex items-center justify-between gap-4 py-3">
979	                <div className="min-w-0">
980	                  <p className="truncate font-serif text-[19px] font-semibold">{r.title}</p>
981	                  {over && (
982	                    <Link href={`/start?draft=${over.id}`} className="link text-[13px]">
983	                      Starting over, {draftLabel(over).toLowerCase()}. Continue
984	                    </Link>
985	                  )}
986	                </div>
987	                <div className="flex shrink-0 items-center gap-3">
988	                  <button className="link text-[13px]" onClick={() => setConfirming(r.id)}>
989	                    Delete
990	                  </button>
991	                  <Link href={`/registry/${r.id}`} className="btn-quiet px-4 py-2.5">
992	                    Open
993	                  </Link>
994	                </div>
995	              </div>
996	              {confirmRow(r.id, "Delete it? The share link stops working and gifts marked on it are lost.", () =>
997	                void remove(() => api(`/api/registries/${r.id}`, { method: "DELETE", body: JSON.stringify({ confirm: true }) })),
998	              )}
999	            </li>
1000	          );
1001	        })}
1002	      </ul>
1003	
1004	      {error && (
1005	        <p role="alert" className="text-[13px] text-danger">
1006	          {error}
1007	        </p>
1008	      )}
1009	
1010	      {!unfinished && (
1011	        <div className="flex flex-wrap items-center gap-x-5 gap-y-2 pt-1 text-[13px]">
1012	          <Link href="/start?new" className="link">
1013	            Start a new registry
1014	          </Link>
1015	          {registries[0] && (
1016	            <Link href={`/start?from=${registries[0].id}`} className="link">
1017	              Start one using answers from {registries[0].title}
1018	            </Link>
1019	          )}
1020	        </div>
1021	      )}
1022	    </section>
1023	  );
1024	}
