/* A product set on a tinted stage. Retailer photos have white backgrounds, so multiply drops them into the tint. */
@utility stage {
  @apply overflow-hidden rounded-[18px];
  & img {
    mix-blend-mode: multiply;
  }
}

@keyframes lamp {
  from {
    opacity: 0.15;
    transform: scale(0.6);
  }
  to {
    opacity: 1;
