"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import { AnswersCard } from "@/components/AnswersCard";
import { describeAnswers } from "@/lib/answers";
import { api } from "@/lib/client";
import type { EditDiff, ParentProfile, Registry } from "@/lib/types";

type Preview = { changes: string[]; diff: EditDiff };

/** The answers the list was built from. Changing them previews how the list would change before anything is saved. */
export function YourAnswers({ registry, onSaved }: { registry: Registry; onSaved: () => Promise<void> }) {
  const [draft, setDraft] = useState<ParentProfile | null>(null);
  const [preview, setPreview] = useState<Preview | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const names = new Map(registry.items.map((i) => [i.id, i.name]));

  async function run(task: () => Promise<void>) {
    setBusy(true);
    setError("");
    try {
      await task();
    } catch (e) {
      setError(e instanceof Error ? e.message : "That didn't go through. Try again.");
    } finally {
      setBusy(false);
    }
  }

  function close() {
    setDraft(null);
    setPreview(null);
    setError("");
  }

  if (!draft) {
    const plain = describeAnswers(registry.profile);
    return (
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0 space-y-1 text-[14px]">
          <p className="font-semibold">Your answers</p>
          <p className="text-muted">{[plain.home, plain.hasCar, plain.feeding, `${plain.budget} budget`].join(", ")}</p>
        </div>
        <button className="btn-quiet shrink-0 px-4 py-2.5" onClick={() => setDraft(registry.profile)}>
          Change answers
        </button>
      </div>
    );
  }

  const listChanges = preview ? preview.diff.remove.length + preview.diff.add.length + preview.diff.swap.length : 0;

  return (
    <AnswersCard
      profile={draft}
      onChange={(next) => {
        setDraft(next);
        setPreview(null);
      }}
      showNames={false}
      title="Your answers"
      intro="Change anything, then see how your list would change. Nothing is saved until you apply it."
    >
      {preview && (
        <div className="space-y-2 rounded-xl bg-raise p-4 text-[14px]" aria-live="polite">
          {preview.changes.length === 0 ? (
            <p>You haven&apos;t changed anything yet.</p>
          ) : listChanges === 0 ? (
            <p>Your list already fits these answers. Save them to keep them.</p>
          ) : (
            <>
              <p className="font-serif text-[16px] text-note italic">{preview.diff.summary}</p>
              <ul className="space-y-1">
                {preview.diff.remove.map((id) => (
                  <li key={id}>Remove {names.get(id)}</li>
                ))}
                {preview.diff.add.map((item) => (
                  <li key={item.name}>Add {item.name}</li>
                ))}
                {preview.diff.swap.map((s) => (
                  <li key={s.id}>Find a different {names.get(s.id)?.toLowerCase()}</li>
                ))}
              </ul>
              <p className="text-[13px] text-muted">Gifted items always stay.</p>
            </>
          )}
        </div>
      )}
      {error && (
        <p role="alert" className="text-[13px] text-danger">
          {error}
        </p>
      )}
      <div className="flex gap-2">
        <button className="btn-quiet flex-1 py-2.5" onClick={close} disabled={busy}>
          Cancel
        </button>
        {preview && preview.changes.length > 0 ? (
          <button
            className="btn-primary flex-1 py-2.5"
            disabled={busy}
            onClick={() =>
              void run(async () => {
                await api(`/api/registries/${registry.id}/answers`, {
                  method: "POST",
                  body: JSON.stringify({ profile: draft, diff: preview.diff }),
                });
                close();
                await onSaved();
              })
            }
          >
            {busy ? "Saving…" : listChanges ? "Apply changes" : "Save answers"}
          </button>
        ) : (
          <button
            className="btn-primary flex-1 py-2.5"
            disabled={busy || Boolean(preview)}
            onClick={() =>
              void run(async () => {
                setPreview(
                  await api<Preview>(`/api/registries/${registry.id}/answers`, {
                    method: "POST",
                    body: JSON.stringify({ profile: draft }),
                  }),
                );
              })
            }
          >
            {busy ? "Checking your list…" : "Preview changes"}
          </button>
        )}
      </div>
    </AnswersCard>
  );
}

/** An inline "are you sure" so a stray tap never starts over or deletes anything. */
function Confirm({
  prompt,
  detail,
  action,
  busy,
  onCancel,
  onConfirm,
}: {
  prompt: string;
  detail: string;
  action: string;
  busy?: boolean;
  onCancel: () => void;
  onConfirm: () => void;
}) {
  return (
    <div className="space-y-3 rounded-xl bg-surface p-4" role="alertdialog" aria-label={prompt}>
      <p className="font-semibold">{prompt}</p>
      <p className="text-[14px] text-muted">{detail}</p>
      <div className="flex gap-2">
        <button className="btn-quiet flex-1 py-2.5" onClick={onCancel} disabled={busy}>
          Cancel
        </button>
        <button className="btn-primary flex-1 py-2.5" onClick={onConfirm} disabled={busy}>
          {action}
        </button>
      </div>
    </div>
  );
}

function giftedCount(registry: Registry) {
  return registry.items.filter((i) => i.purchased).length;
}

export function StartOverLink({ registry, label = "Start this registry over" }: { registry: Registry; label?: string }) {
  const router = useRouter();
  const [asking, setAsking] = useState(false);
  const gifted = giftedCount(registry);

  if (!asking) {
    return (
      <button className="link text-[13px]" onClick={() => setAsking(true)}>
        {label}
      </button>
    );
  }
  return (
    <Confirm
      prompt="Start this registry over?"
      detail={`You'll answer the questions again and get a fresh list. Your share link, names, note, and address stay${
        gifted ? `, and the ${gifted === 1 ? "gift" : `${gifted} gifts`} already bought stay on the list` : ""
      }.`}
      action="Start over"
      onCancel={() => setAsking(false)}
      onConfirm={() => router.push(`/start?registry=${registry.id}`)}
    />
  );
}

export function DeleteRegistry({ registry }: { registry: Registry }) {
  const router = useRouter();
  const [asking, setAsking] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const gifted = giftedCount(registry);

  async function remove() {
    setBusy(true);
    setError("");
    try {
      await api(`/api/registries/${registry.id}`, { method: "DELETE", body: JSON.stringify({ confirm: true }) });
      router.push("/");
    } catch (e) {
      setBusy(false);
      setError(e instanceof Error ? e.message : "It couldn't be deleted. Try again.");
    }
  }

  if (!asking) {
    return (
      <button className="link text-[13px]" onClick={() => setAsking(true)}>
        Delete registry
      </button>
    );
  }
  return (
    <div className="space-y-2">
      <Confirm
        prompt={`Delete ${registry.title}?`}
        detail={`The share link will stop working${
          gifted ? ` and the record of ${gifted === 1 ? "1 gift" : `${gifted} gifts`} will be lost` : ""
        }. This can't be undone.`}
        action={busy ? "Deleting…" : "Delete"}
        busy={busy}
        onCancel={() => setAsking(false)}
        onConfirm={() => void remove()}
      />
      {error && (
        <p role="alert" className="text-[13px] text-danger">
          {error}
        </p>
      )}
    </div>
  );
}
"use client";

import { useCallback, useEffect, useState } from "react";
import { api } from "@/lib/client";
import type { AddressRequest, Registry, ShippingAddress } from "@/lib/types";

const EMPTY_ADDRESS: ShippingAddress = {
  recipient: "",
  line1: "",
  line2: "",
  city: "",
  region: "",
  postalCode: "",
  country: "United States",
};

const POLL_MS = 30000;

type Private = { address: ShippingAddress | null; requests: AddressRequest[] };

/** Names, a note for family, the private shipping address, and who has asked for it. */
export function RegistryDetails({ registry, onSaved }: { registry: Registry; onSaved: () => Promise<void> }) {
  const [data, setData] = useState<Private | null>(null);
  const [editing, setEditing] = useState(false);

  const load = useCallback(async () => {
    try {
      setData(await api<Private>(`/api/registries/${registry.id}/details`));
    } catch {
      // The rest of the page still works; the next poll retries.
    }
  }, [registry.id]);

  useEffect(() => {
    void load();
    const timer = setInterval(() => void load(), POLL_MS);
    const onFocus = () => void load();
    window.addEventListener("focus", onFocus);
    return () => {
      clearInterval(timer);
      window.removeEventListener("focus", onFocus);
    };
  }, [load]);

  const people = [registry.parentNames, registry.babyName && `baby ${registry.babyName}`].filter(Boolean).join(", ");

  return (
    <section className="space-y-4" aria-label="Registry details">
      {editing ? (
        <DetailsForm
          registry={registry}
          address={data?.address ?? null}
          onCancel={() => setEditing(false)}
          onSaved={async () => {
            setEditing(false);
            await Promise.all([onSaved(), load()]);
          }}
        />
      ) : (
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0 space-y-1 text-[14px]">
            <p className={people ? "" : "text-muted"}>{people ? `For ${people}` : "No names added yet"}</p>
            <p className="text-muted">
              {data?.address ? `Shipping to ${data.address.city || data.address.line1}, shared only when you approve` : "No shipping address yet"}
            </p>
          </div>
          <button className="btn-quiet shrink-0 px-4 py-2.5" onClick={() => setEditing(true)}>
            Edit details
          </button>
        </div>
      )}
      {data && <AddressRequests registryId={registry.id} requests={data.requests} hasAddress={Boolean(data.address)} onChange={load} />}
    </section>
  );
}

function DetailsForm({
  registry,
  address,
  onCancel,
  onSaved,
}: {
  registry: Registry;
  address: ShippingAddress | null;
  onCancel: () => void;
  onSaved: () => Promise<void>;
}) {
  const [details, setDetails] = useState({
    title: registry.title,
    parentNames: registry.parentNames,
    babyName: registry.babyName,
    familyNote: registry.familyNote,
  });
  const [addr, setAddr] = useState<ShippingAddress>(address ?? EMPTY_ADDRESS);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const addressStarted = [addr.recipient, addr.line1, addr.line2, addr.city, addr.region, addr.postalCode].some((v) => v.trim());

  async function save() {
    setBusy(true);
    setError("");
    try {
      await api(`/api/registries/${registry.id}/details`, {
        method: "PUT",
        body: JSON.stringify({ details, address: addressStarted ? addr : null }),
      });
      await onSaved();
    } catch (e) {
      setError(e instanceof Error ? e.message : "That didn't save. Try again.");
    } finally {
      setBusy(false);
    }
  }

  const field = (label: string, value: string, onChange: (v: string) => void, props: React.InputHTMLAttributes<HTMLInputElement> = {}) => (
    <label className="block space-y-1.5">
      <span className="text-[13px] text-muted">{label}</span>
      <input value={value} onChange={(e) => onChange(e.target.value)} className="field" {...props} />
    </label>
  );
  const setA = (key: keyof ShippingAddress) => (v: string) => setAddr((a) => ({ ...a, [key]: v }));

  return (
    <form
      className="space-y-5 rounded-xl bg-surface p-5"
      onSubmit={(e) => {
        e.preventDefault();
        void save();
      }}
    >
      <div className="space-y-3">
        {field("Registry title", details.title, (title) => setDetails((d) => ({ ...d, title })), { required: true, maxLength: 80 })}
        {field("Your names", details.parentNames, (parentNames) => setDetails((d) => ({ ...d, parentNames })), {
          placeholder: "Maya and Jordan",
          maxLength: 80,
          autoComplete: "name",
        })}
        {field("Baby's name (optional)", details.babyName, (babyName) => setDetails((d) => ({ ...d, babyName })), {
          placeholder: "Not decided yet is fine",
          maxLength: 40,
        })}
        <label className="block space-y-1.5">
          <span className="text-[13px] text-muted">A note for family (shown on your share page)</span>
          <textarea
            value={details.familyNote}
            onChange={(e) => setDetails((d) => ({ ...d, familyNote: e.target.value }))}
            maxLength={500}
            rows={3}
            placeholder="Thank you for thinking of us. Gently used is welcome!"
            className="field resize-none"
          />
        </label>
      </div>

      <fieldset className="space-y-3">
        <legend className="font-semibold">Shipping address</legend>
        <p className="text-[13px] text-muted">
          Private. Family can ask for it from your share page, and you choose who gets it.
        </p>
        {field("Name on the package", addr.recipient, setA("recipient"), { autoComplete: "shipping name" })}
        {field("Street address", addr.line1, setA("line1"), { autoComplete: "shipping address-line1" })}
        {field("Apartment, unit (optional)", addr.line2, setA("line2"), { autoComplete: "shipping address-line2" })}
        <div className="grid grid-cols-2 gap-3">
          {field("City", addr.city, setA("city"), { autoComplete: "shipping address-level2" })}
          {field("State", addr.region, setA("region"), { autoComplete: "shipping address-level1" })}
          {field("ZIP code", addr.postalCode, setA("postalCode"), { autoComplete: "shipping postal-code", inputMode: "numeric" })}
          {field("Country", addr.country, setA("country"), { autoComplete: "shipping country-name" })}
        </div>
        {address && (
          <button type="button" className="link text-[13px]" onClick={() => setAddr({ ...EMPTY_ADDRESS, country: "" })}>
            Remove address
          </button>
        )}
      </fieldset>

      {error && (
        <p role="alert" className="text-[13px] text-danger">
          {error}
        </p>
      )}
      <div className="flex gap-2">
        <button type="button" className="btn-quiet flex-1 py-2.5" onClick={onCancel} disabled={busy}>
          Cancel
        </button>
        <button className="btn-primary flex-1 py-2.5" disabled={busy}>
          {busy ? "Saving…" : "Save"}
        </button>
      </div>
    </form>
  );
}

function AddressRequests({
  registryId,
  requests,
  hasAddress,
  onChange,
}: {
  registryId: string;
  requests: AddressRequest[];
  hasAddress: boolean;
  onChange: () => Promise<void>;
}) {
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState("");
  const pending = requests.filter((r) => r.status === "pending");
  const approved = requests.filter((r) => r.status === "approved");

  async function decide(requestId: string, decision: "approved" | "declined") {
    setBusy(requestId);
    setError("");
    try {
      await api(`/api/registries/${registryId}/details`, { method: "POST", body: JSON.stringify({ requestId, decision }) });
      await onChange();
    } catch (e) {
      setError(e instanceof Error ? e.message : "That didn't go through. Try again.");
    } finally {
      setBusy(null);
    }
  }

  if (!pending.length && !approved.length) return null;

  return (
    <div className="space-y-3">
      {pending.length > 0 && (
        <div className="space-y-3 rounded-xl bg-surface p-4">
          <p className="font-semibold">
            {pending.length === 1 ? "1 person is" : `${pending.length} people are`} asking for your address
          </p>
          {!hasAddress && <p className="text-[13px] text-muted">Add an address in your details before sharing it.</p>}
          <ul className="space-y-4">
            {pending.map((r) => (
              <li key={r.id} className="space-y-2">
                <div className="text-[14px]">
                  <p>
                    <span className="font-semibold">{r.name}</span> <span className="text-muted">({r.contact})</span>
                  </p>
                  {r.message && <p className="font-serif text-note italic">&ldquo;{r.message}&rdquo;</p>}
                </div>
                <div className="flex gap-2">
                  <button className="btn-quiet flex-1 py-2" onClick={() => void decide(r.id, "declined")} disabled={busy === r.id}>
                    Decline
                  </button>
                  <button
                    className="btn-primary flex-1 py-2"
                    onClick={() => void decide(r.id, "approved")}
                    disabled={busy === r.id || !hasAddress}
                  >
                    Share address
                  </button>
                </div>
              </li>
            ))}
          </ul>
        </div>
      )}
      {approved.length > 0 && (
        <details className="text-[13px] text-muted">
          <summary className="cursor-pointer">Address shared with {approved.length === 1 ? approved[0].name : `${approved.length} people`}</summary>
          <ul className="mt-2 space-y-1">
            {approved.map((r) => (
              <li key={r.id} className="flex items-center justify-between gap-3">
                <span className="truncate">
                  {r.name} ({r.contact})
                </span>
                <button className="link shrink-0" onClick={() => void decide(r.id, "declined")} disabled={busy === r.id}>
                  Stop sharing
                </button>
              </li>
            ))}
          </ul>
        </details>
      )}
      {error && (
        <p role="alert" className="text-[13px] text-danger">
          {error}
        </p>
      )}
    </div>
  );
}
import { RETAILER_LABELS, type Offer } from "@/lib/types";

/** Link a retailer-provided rating to the product page, where shoppers can read the reviews. */
export function ProductRating({ offer, className = "" }: { offer?: Offer; className?: string }) {
  // Older saved catalog offers contain a price-tier estimate, not a customer rating.
  const rating = offer?.externalId.startsWith("catalog:") ? null : offer?.rating;
  if (!offer || offer.externalId.startsWith("search:")) return null;
  const hasRating = rating != null && Number.isFinite(rating) && rating > 0 && rating <= 5;

  const label = hasRating
    ? `${rating.toFixed(1)} out of 5 stars at ${RETAILER_LABELS[offer.retailer]}. Open product page to read reviews`
    : `Open ${RETAILER_LABELS[offer.retailer]} product page to read reviews`;
  return (
    <a
      href={offer.url}
      target="_blank"
      rel="noopener noreferrer sponsored"
      aria-label={label}
      className={`inline-flex w-fit items-center gap-1.5 text-[13px] text-muted hover:text-text ${className}`}
    >
      {hasRating && (
        <span aria-hidden="true" className="relative inline-block whitespace-nowrap tracking-[1px] text-line">
          ★★★★★
          <span
            className="absolute inset-y-0 left-0 overflow-hidden whitespace-nowrap text-[#d79a40]"
            style={{ width: `${rating * 20}%` }}
          >
            ★★★★★
          </span>
        </span>
      )}
      {hasRating && <span className="tabular-nums">{rating.toFixed(1)}</span>}
      <span className="underline decoration-line underline-offset-2">
        Read reviews{!hasRating && ` at ${RETAILER_LABELS[offer.retailer]}`}
      </span>
    </a>
  );
}
import type { Offer } from "@/lib/types";

const STAGES = ["bg-stage-lavender", "bg-stage-blush", "bg-stage-butter"];

/** The same item always gets the same tint, so a list reads as a calm mix rather than a pattern. */
function stageFor(label: string) {
  let hash = 0;
  for (const char of label) hash = (hash * 31 + char.charCodeAt(0)) | 0;
  return STAGES[Math.abs(hash) % STAGES.length];
}

/** A product photo set on a soft tinted stage. Without a photo, a quiet outlined stage names the item instead. */
export function ProductPhoto({ offer, label, className = "" }: { offer?: Offer; label: string; className?: string }) {
  if (!offer?.imageUrl) {
    return (
      <div className={`flex shrink-0 items-center justify-center rounded-[18px] border border-dashed border-line ${className}`}>
        <span className="px-2 text-center font-serif text-[13px] leading-snug text-muted">{label}</span>
      </div>
    );
  }
  return (
    <div className={`stage flex shrink-0 items-center justify-center ${stageFor(label)} ${className}`}>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={offer.imageUrl} alt="" loading="lazy" className="h-full w-full object-contain p-[10%]" />
    </div>
  );
}
